20	constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;
21	constexpr int64_t kCacheLineSize = 512;
22	
23	at::Tensor foreach_addcdiv_list(
24	    const at::Tensor &x1, const at::Tensor &x2,
25	    const at::Tensor &x3, const at::Tensor &scalars)
26	{
27	    TORCH_CHECK(x1.scalar_type() == at::kFloat || x1.scalar_type() == at::kHalf ||
28	                   x1.scalar_type() == at::kBFloat16,
29	        "unsupported dtype");
30	    TORCH_CHECK(x1.scalar_type() == x2.scalar_type() &&
31	                   x1.scalar_type() == x3.scalar_type() &&
32	                   x1.scalar_type() == scalars.scalar_type(),
33	        "all inputs must have the same dtype");
34	    TORCH_CHECK(x1.numel() == x2.numel(), "numel mismatch");
35	    TORCH_CHECK(x1.numel() == x3.numel(), "numel mismatch");
36	    TORCH_CHECK(x1.numel() == scalars.numel(), "numel mismatch");
37	
38	    auto x1Contig = x1.contiguous();
39	    auto x2Contig = x2.contiguous();
40	    auto x3Contig = x3.contiguous();
41	    auto sContig = scalars.contiguous();
42	
43	    auto dtype = x1.scalar_type();
44	    int64_t dtypeFlag = 0;
45	    if (dtype == at::kHalf) {
46	        dtypeFlag = 1;
47	    } else if (dtype == at::kBFloat16) {
48	        dtypeFlag = 2;
49	    }
50	
51	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
52	    int32_t coreNum = static_cast<int32_t>(ascendcPlatform->GetCoreNumAiv());
53	    coreNum = std::min<int32_t>(coreNum, DEFAULT_NUM_PHYSICAL_CORES);
54	    if (coreNum <= 0) coreNum = 1;
55	
56	    uint64_t ubSizeVal;
57	    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSizeVal);
58	    int64_t ubSize = static_cast<int64_t>(ubSizeVal);
59	
60	    int64_t totalLen = x1Contig.numel();
61	    int32_t dtypeSize = static_cast<int32_t>(c10::elementSize(dtype));
62	
63	    // Tile size calculation:
64	    // fp16/bf16: 5 VECIN/VECOUT(fp16) + 5 Cast VECCALC(fp32) = 5*2+5*4=30 bytes/elem
65	    // fp32: 5 VECIN/VECOUT(fp32) + 1 tmp VECCALC(fp32) = 6*4=24 bytes/elem
66	    int64_t bytesPerElem = (dtype == at::kFloat) ? 24 : 30;
67	    int64_t kDataUbBudget = ubSize * 3 / 10;  // ~30% of UB, conservative
68	    int32_t tileLen = static_cast<int32_t>(kDataUbBudget / bytesPerElem);
69	    tileLen = (tileLen / 32) * 32;
70	    if (tileLen < 32) tileLen = 32;
71	    if (tileLen > 4096) tileLen = 4096;
72	
73	    // Block-level partition with cache line alignment
74	    int32_t elemPerCL = static_cast<int32_t>(kCacheLineSize / dtypeSize);
75	    if (elemPerCL < 1) elemPerCL = 256;
76	    int32_t elemsPerBlock = static_cast<int32_t>((totalLen + coreNum - 1) / coreNum);
77	    elemsPerBlock = ((elemsPerBlock + elemPerCL - 1) / elemPerCL) * elemPerCL;
78	    if (elemsPerBlock < elemPerCL) elemsPerBlock = elemPerCL;
79	
80	    int32_t formerNum = static_cast<int32_t>(totalLen / elemsPerBlock);
81	    int32_t formerLen = elemsPerBlock;
82	    int32_t tailLen = static_cast<int32_t>(totalLen % elemsPerBlock);
83	    int32_t tailNum = (tailLen > 0) ? 1 : 0;
84	
85	    int32_t numTilesPerBlock = static_cast<int32_t>((elemsPerBlock + tileLen - 1) / tileLen);
86	
87	    auto yOut = at::empty_like(x1Contig);
88	
89	    // All params as left values for EXEC_KERNEL_CMD
90	    int32_t totalLenI32 = static_cast<int32_t>(totalLen);
91	    uint32_t blockDim = static_cast<uint32_t>(formerNum + tailNum);
92	
93	    EXEC_KERNEL_CMD(foreach_addcdiv_list, blockDim,
94	                    x1Contig, x2Contig, x3Contig, sContig, yOut,
95	                    totalLenI32, tileLen,
96	                    formerNum, formerLen, tailNum, tailLen,
97	                    elemsPerBlock, numTilesPerBlock, dtypeFlag);
98	
99	    return yOut;
100	}
101	
