7	// ForeachAddcdivList: Y = X1 + X2 / X3 * Scalars
8	// Adapted from working AddRmsNorm kernel pattern.
9	
10	#include "kernel_operator.h"
11	
12	constexpr int32_t BUFFER_NUM = 1;
13	
14	// ---------------------------------------------------------------------------
15	// GM <-> UB helpers
16	// ---------------------------------------------------------------------------
17	
18	__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
19	{
20	    if (b == 0U) { return 0U; }
21	    return (a + b - 1U) / b;
22	}
23	
24	template <typename T>
25	__aicore__ inline void LoadGmToUb(
26	    AscendC::LocalTensor<T> &dst,
27	    AscendC::GlobalTensor<T> src,
28	    uint32_t count)
29	{
30	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
31	    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
32	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
33	}
34	
35	template <typename T>
36	__aicore__ inline void StoreUbToGm(
37	    AscendC::GlobalTensor<T> dst,
38	    AscendC::LocalTensor<T> &src,
39	    uint32_t count)
40	{
41	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
42	    AscendC::DataCopyPad(dst, src, copyParams);
43	}
