45	// ---------------------------------------------------------------------------
46	// Strategy-agnostic helpers (adapted from AddRmsNorm)
47	// ---------------------------------------------------------------------------
48	
49	template <typename T>
50	__aicore__ inline AscendC::RoundMode OutputRoundModeHelper()
51	{
52	    if constexpr (std::is_same_v<T, bfloat16_t>) {
53	        return AscendC::RoundMode::CAST_ROUND;
54	    }
55	    return AscendC::RoundMode::CAST_NONE;
56	}
57	
58	template <typename T>
59	__aicore__ inline void PrepareInputTensorHelper(
60	    AscendC::LocalTensor<float> &dst,
61	    AscendC::LocalTensor<T> &src,
62	    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf,
63	    int32_t count)
64	{
65	    if constexpr (std::is_same_v<T, float>) {
66	        dst = src.template ReinterpretCast<float>();
67	    } else {
68	        dst = castBuf.Get<float>();
69	        AscendC::Cast(dst, src, AscendC::RoundMode::CAST_NONE, count);
70	        AscendC::PipeBarrier<PIPE_V>();
71	    }
72	}
73	
74	template <typename T>
75	__aicore__ inline void PrepareOutputTensorHelper(
76	    AscendC::LocalTensor<float> &dst,
77	    AscendC::LocalTensor<T> &out,
78	    AscendC::TBuf<AscendC::TPosition::VECCALC> &castBuf)
79	{
80	    if constexpr (std::is_same_v<T, float>) {
81	        dst = out.template ReinterpretCast<float>();
82	    } else {
83	        dst = castBuf.Get<float>();
84	    }
85	}
