87	// =========================================================================
88	// Main kernel
89	// =========================================================================
90	
91	template <typename dataType>
92	class KernelForeachAddcdivList {
93	public:
94	    __aicore__ inline void Init(
95	        GM_ADDR x1Gm, GM_ADDR x2Gm, GM_ADDR x3Gm,
96	        GM_ADDR scalarsGm, GM_ADDR yGm,
97	        int32_t totalLength, int32_t tileLength,
98	        int32_t formerNum, int32_t formerLength,
99	        int32_t tailNum, int32_t tailLength,
100	        int32_t elementsPerBlock, int32_t numTilesPerBlock)
101	    {
102	        totalLen_ = totalLength;
103	        N_ = tileLength;
104	        formerNum_ = formerNum;
105	        formerLength_ = formerLength;
106	        tailNum_ = tailNum;
107	        tailLength_ = tailLength;
108	        elemsPerBlock_ = elementsPerBlock;
109	        tilesPerBlock_ = numTilesPerBlock;
110	
111	        x1GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x1Gm), totalLen_);
112	        x2GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x2Gm), totalLen_);
113	        x3GM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(x3Gm), totalLen_);
114	        sGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(scalarsGm), totalLen_);
115	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(yGm), totalLen_);
116	
117	        if ASCEND_IS_AIV {
118	            pipe.InitBuffer(x1InQueue_, BUFFER_NUM, N_ * sizeof(dataType));
119	            pipe.InitBuffer(x2InQueue_, BUFFER_NUM, N_ * sizeof(dataType));
120	            pipe.InitBuffer(x3InQueue_, BUFFER_NUM, N_ * sizeof(dataType));
121	            pipe.InitBuffer(sInQueue_,  BUFFER_NUM, N_ * sizeof(dataType));
122	            pipe.InitBuffer(yOutQueue_, BUFFER_NUM, N_ * sizeof(dataType));
123	
124	            if constexpr (!std::is_same_v<dataType, float>) {
125	                pipe.InitBuffer(x1CastBuf_, N_ * sizeof(float));
126	                pipe.InitBuffer(x2CastBuf_, N_ * sizeof(float));
127	                pipe.InitBuffer(x3CastBuf_, N_ * sizeof(float));
128	                pipe.InitBuffer(sCastBuf_,  N_ * sizeof(float));
129	                pipe.InitBuffer(yCastBuf_,  N_ * sizeof(float));
130	            } else {
131	                pipe.InitBuffer(tmpBuf_, N_ * sizeof(float));
132	            }
133	        }
134	    }
135	
136	    __aicore__ inline void Process()
137	    {
138	        if ASCEND_IS_AIV {
139	            int32_t coreIdx = AscendC::GetBlockIdx();
140	            int32_t blockOffset;
141	
142	            if (coreIdx < formerNum_) {
143	                blockOffset = coreIdx * formerLength_;
144	            } else if (tailNum_ > 0 && coreIdx == formerNum_) {
145	                blockOffset = formerNum_ * formerLength_;
146	            } else {
147	                return;
148	            }
149	
150	            for (int32_t t = 0; t < tilesPerBlock_; ++t) {
151	                int32_t tileStart = blockOffset + t * N_;
152	                int32_t curLen = N_;
153	                if (tileStart + curLen > totalLen_) {
154	                    curLen = totalLen_ - tileStart;
155	                    if (curLen <= 0) continue;
156	                }
157	                // Ensure the core hasn't exceeded its assigned range
158	                int32_t blockEnd = blockOffset + elemsPerBlock_;
159	                if (blockEnd > totalLen_) blockEnd = totalLen_;
160	                if (tileStart >= blockEnd) continue;
161	                if (tileStart + curLen > blockEnd) {
162	                    curLen = blockEnd - tileStart;
163	                }
164	
165	                CopyIn(tileStart, curLen);
166	                Compute(curLen);
167	                CopyOut(tileStart, curLen);
168	            }
169	        }
170	    }
171	
172	private:
173	    __aicore__ inline void CopyIn(int32_t start, int32_t count)
174	    {
175	        x1InLocal_ = x1InQueue_.AllocTensor<dataType>();
176	        LoadGmToUb(x1InLocal_, x1GM_[start], static_cast<uint32_t>(count));
177	        x1InQueue_.EnQue(x1InLocal_);
178	
179	        x2InLocal_ = x2InQueue_.AllocTensor<dataType>();
180	        LoadGmToUb(x2InLocal_, x2GM_[start], static_cast<uint32_t>(count));
181	        x2InQueue_.EnQue(x2InLocal_);
182	
183	        x3InLocal_ = x3InQueue_.AllocTensor<dataType>();
184	        LoadGmToUb(x3InLocal_, x3GM_[start], static_cast<uint32_t>(count));
185	        x3InQueue_.EnQue(x3InLocal_);
186	
187	        sInLocal_ = sInQueue_.AllocTensor<dataType>();
188	        LoadGmToUb(sInLocal_, sGM_[start], static_cast<uint32_t>(count));
189	        sInQueue_.EnQue(sInLocal_);
190	    }
191	
192	    __aicore__ inline void Compute(int32_t count)
193	    {
194	        yOutLocal_ = yOutQueue_.AllocTensor<dataType>();
195	        PrepareOutputTensorHelper<dataType>(yLocal_, yOutLocal_, yCastBuf_);
196	
197	        x1InLocal_ = x1InQueue_.DeQue<dataType>();
198	        PrepareInputTensorHelper<dataType>(x1Local_, x1InLocal_, x1CastBuf_, count);
199	
200	        x2InLocal_ = x2InQueue_.DeQue<dataType>();
201	        PrepareInputTensorHelper<dataType>(x2Local_, x2InLocal_, x2CastBuf_, count);
202	
203	        x3InLocal_ = x3InQueue_.DeQue<dataType>();
204	        PrepareInputTensorHelper<dataType>(x3Local_, x3InLocal_, x3CastBuf_, count);
205	
206	        sInLocal_ = sInQueue_.DeQue<dataType>();
207	        PrepareInputTensorHelper<dataType>(sLocal_, sInLocal_, sCastBuf_, count);
208	
209	        // --- Compute: y = x1 + x2/x3 * s ---
210	        if constexpr (std::is_same_v<dataType, float>) {
211	            // tmp = x2 / x3
212	            AscendC::Div(tmpLocal_, x2Local_, x3Local_, count);
213	            // tmp = tmp * s
214	            AscendC::Mul(tmpLocal_, tmpLocal_, sLocal_, count);
215	            // y = x1 + tmp
216	            AscendC::Add(yLocal_, x1Local_, tmpLocal_, count);
217	            // yLocal_ IS yOutLocal_ (ReinterpretCast), result is already in VECOUT
218	        } else {
219	            // Compute on VECCALC buffers (x1Local_..sLocal_ are VECCALC)
220	            // x2Local_ = x2 / x3 (reuse VECCALC x2)
221	            AscendC::Div(x2Local_, x2Local_, x3Local_, count);
222	            // x2Local_ = x2Local_ * s (reuse VECCALC x2)
223	            AscendC::Mul(x2Local_, x2Local_, sLocal_, count);
224	            // x1Local_ = x1 + x2Local_ (reuse VECCALC x1)
225	            AscendC::Add(x1Local_, x1Local_, x2Local_, count);
226	            // Cast x1Local_(VECCALC) → yOutLocal_(VECOUT)
227	            AscendC::Cast(yOutLocal_, x1Local_, OutputRoundModeHelper<dataType>(), count);
228	            AscendC::PipeBarrier<PIPE_V>();
229	        }
230	
231	        yOutQueue_.EnQue(yOutLocal_);
232	
233	        x1InQueue_.FreeTensor(x1InLocal_);
234	        x2InQueue_.FreeTensor(x2InLocal_);
235	        x3InQueue_.FreeTensor(x3InLocal_);
236	        sInQueue_.FreeTensor(sInLocal_);
237	    }
238	
239	    __aicore__ inline void CopyOut(int32_t start, int32_t count)
240	    {
241	        yOutLocal_ = yOutQueue_.DeQue<dataType>();
242	        StoreUbToGm(yGM_[start], yOutLocal_, static_cast<uint32_t>(count));
243	        yOutQueue_.FreeTensor(yOutLocal_);
244	    }
245	
246	private:
247	    AscendC::TPipe pipe;
248	    int32_t totalLen_;
249	    int32_t N_;  // tileLength (follows AddRmsNorm naming)
250	    int32_t formerNum_;
251	    int32_t formerLength_;
252	    int32_t tailNum_;
253	    int32_t tailLength_;
254	    int32_t elemsPerBlock_;
255	    int32_t tilesPerBlock_;
256	
257	    AscendC::GlobalTensor<dataType> x1GM_;
258	    AscendC::GlobalTensor<dataType> x2GM_;
259	    AscendC::GlobalTensor<dataType> x3GM_;
260	    AscendC::GlobalTensor<dataType> sGM_;
261	    AscendC::GlobalTensor<dataType> yGM_;
262	
263	    AscendC::TQue<AscendC::QuePosition::VECIN,  BUFFER_NUM> x1InQueue_;
264	    AscendC::TQue<AscendC::QuePosition::VECIN,  BUFFER_NUM> x2InQueue_;
265	    AscendC::TQue<AscendC::QuePosition::VECIN,  BUFFER_NUM> x3InQueue_;
266	    AscendC::TQue<AscendC::QuePosition::VECIN,  BUFFER_NUM> sInQueue_;
267	    AscendC::TQue<AscendC::QuePosition::VECOUT, BUFFER_NUM> yOutQueue_;
268	
269	    AscendC::TBuf<AscendC::TPosition::VECCALC> x1CastBuf_;
270	    AscendC::TBuf<AscendC::TPosition::VECCALC> x2CastBuf_;
271	    AscendC::TBuf<AscendC::TPosition::VECCALC> x3CastBuf_;
272	    AscendC::TBuf<AscendC::TPosition::VECCALC> sCastBuf_;
273	    AscendC::TBuf<AscendC::TPosition::VECCALC> yCastBuf_;
274	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;
275	
276	    AscendC::LocalTensor<dataType> x1InLocal_;
277	    AscendC::LocalTensor<dataType> x2InLocal_;
278	    AscendC::LocalTensor<dataType> x3InLocal_;
279	    AscendC::LocalTensor<dataType> sInLocal_;
280	    AscendC::LocalTensor<dataType> yOutLocal_;
281	
282	    AscendC::LocalTensor<float> x1Local_;
283	    AscendC::LocalTensor<float> x2Local_;
284	    AscendC::LocalTensor<float> x3Local_;
285	    AscendC::LocalTensor<float> sLocal_;
286	    AscendC::LocalTensor<float> yLocal_;
287	    AscendC::LocalTensor<float> tmpLocal_;
288	};
289	
290	extern "C" __global__ __aicore__ void foreach_addcdiv_list(
291	    GM_ADDR x1Gm, GM_ADDR x2Gm, GM_ADDR x3Gm,
292	    GM_ADDR scalarsGm, GM_ADDR yGm,
293	    int32_t totalLength, int32_t tileLength,
294	    int32_t formerNum, int32_t formerLength,
295	    int32_t tailNum, int32_t tailLength,
296	    int32_t elementsPerBlock, int32_t numTilesPerBlock,
297	    int32_t dtypeFlag)
298	{
299	    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_1);
300	
301	    if (dtypeFlag == 0) {
302	        KernelForeachAddcdivList<float> kernel;
303	        kernel.Init(x1Gm, x2Gm, x3Gm, scalarsGm, yGm,
304	                    totalLength, tileLength, formerNum, formerLength,
305	                    tailNum, tailLength, elementsPerBlock, numTilesPerBlock);
306	        kernel.Process();
307	    } else if (dtypeFlag == 1) {
308	        KernelForeachAddcdivList<half> kernel;
309	        kernel.Init(x1Gm, x2Gm, x3Gm, scalarsGm, yGm,
310	                    totalLength, tileLength, formerNum, formerLength,
311	                    tailNum, tailLength, elementsPerBlock, numTilesPerBlock);
312	        kernel.Process();
313	    } else {
314	        KernelForeachAddcdivList<bfloat16_t> kernel;
315	        kernel.Init(x1Gm, x2Gm, x3Gm, scalarsGm, yGm,
316	                    totalLength, tileLength, formerNum, formerLength,
317	                    tailNum, tailLength, elementsPerBlock, numTilesPerBlock);
318	        kernel.Process();
319	    }
320	}
