12	/* !
13	 * \file erf.asc
14	 * \brief 本样例基于Erf高阶API实现误差函数计算功能，按元素做高斯误差函数计算
15	 */
16	
17	#include "acl/acl.h"
18	#include "data_utils.h"
19	#include "kernel_operator.h"
