21	#ifdef ASCENDC_CPU_DEBUG
22	#include "cpu_debug_launch.h"
23	#endif
24	
25	struct ErfCustomTilingData {
26	    uint32_t totalLength;
27	    uint32_t tileNum;
28	};
29	
30	void GenerateTilingData(uint8_t* tilingBuf, const uint32_t totalLength, const uint32_t coreNum)
31	{
32	    ErfCustomTilingData* tiling = reinterpret_cast<ErfCustomTilingData*>(tilingBuf);
33	
34	    tiling->totalLength = totalLength;
35	    tiling->tileNum = coreNum;
36	}
37	
38	namespace MyCustomKernel {
39	constexpr int32_t BUFFER_NUM = 2;
40	
41	/**
42	 * @brief Erf核函数实现类，演示Erf API的使用场景
43	 * @tparam T 数据类型
44	 */
45	template <typename T>
46	class KernelErf {
47	public:
48	    __aicore__ inline KernelErf() {}
49	    __aicore__ inline void Init(__gm__ uint8_t* x, __gm__ uint8_t* y, ErfCustomTilingData tilingData, AscendC::TPipe* pipeIn)
50	    {
51	        ASCENDC_ASSERT(AscendC::GetBlockNum() != 0, { KERNEL_LOG(KERNEL_ERROR, "block dim can not be zero!"); });
52	        this->tileNum = tilingData.tileNum;
53	        this->blockLength = tilingData.totalLength / AscendC::GetBlockNum();
54	        this->tileLength = this->blockLength / tileNum / BUFFER_NUM;
55	
56	        xGm.SetGlobalBuffer((__gm__ T*)x + this->blockLength * AscendC::GetBlockIdx(), this->blockLength);
57	        yGm.SetGlobalBuffer((__gm__ T*)y + this->blockLength * AscendC::GetBlockIdx(), this->blockLength);
58	
59	        pipe = pipeIn;
60	        pipe->InitBuffer(inQueueX, BUFFER_NUM, this->tileLength * sizeof(T));
61	        pipe->InitBuffer(outQueueY, BUFFER_NUM, this->tileLength * sizeof(T));
62	    }
63	    __aicore__ inline void Process()
64	    {
65	        int32_t loopCount = this->tileNum * BUFFER_NUM;
66	        for (int32_t i = 0; i < loopCount; i++) {
67	            CopyIn(i);
68	            Compute(i);
69	            CopyOut(i);
70	        }
71	    }
72	
73	private:
74	    __aicore__ inline void CopyIn(int32_t progress)
75	    {
76	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
77	        AscendC::DataCopy(xLocal, xGm[progress * this->tileLength], this->tileLength);
78	        inQueueX.EnQue(xLocal);
79	    }
80	    __aicore__ inline void Compute(int32_t progress)
81	    {
82	        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
83	        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
84	        // 使用Erf接口计算高斯误差函数
85	        // 模板参数：
86	        //   - T: 输入输出数据类型
87	        //   - false: 是否复用源操作数
88	        // 参数说明：
89	        //   - yLocal: 输出Tensor，存储计算结果
90	        //   - xLocal: 输入Tensor
91	        //   - this->tileLength: 计算元素个数
